const b = $input.first().json.body || {};
const action = String(b.action || '');
const uuid = /^[0-9a-f-]{36}$/;
return [{ json: {
  action,
  etudiant_id: uuid.test(String(b.etudiant_id || '')) ? String(b.etudiant_id) : null,
  session_id: uuid.test(String(b.session_id || '')) ? String(b.session_id) : null,
  message: String(b.message || '').trim().slice(0, 2000),
  consentement: String(b.consentement).toLowerCase() === 'true',
} }];

// Garde-fous : l'agent se connecte au compte CAF rangé dans le coffre H de Margot.
// Il n'est donc proposé QUE pour le dossier de Margot, jamais pour un autre étudiant.
const COMPTE_AUTORISE = 'compte-demo@example.com';
const q = $('Lire la requête').first().json;
const e = $("Lire l'étudiant").first().json || {};
const d = $input.all().map(i => i.json).find(x => x && x.id) || null;
let erreur = null;
if (!['lancer', 'repondre', 'refuser'].includes(q.action)) erreur = 'Action inconnue.';
else if (!q.etudiant_id || !e.id) erreur = "Dossier introuvable : dépose d'abord tes documents.";
else if (String(e.email || '').toLowerCase() !== COMPTE_AUTORISE) erreur = "La demande APL automatique n'est disponible que pour le compte de démonstration relié à un compte CAF.";
else if (!d) erreur = "Fais d'abord la simulation APL.";
else if (q.action === 'lancer' && !q.consentement) erreur = "Il faut accepter que l'agent prépare ta demande.";
else if (q.action === 'lancer' && d.resultat_agent?.demande?.statut === 'en_cours') erreur = "Une préparation de demande est déjà en cours : ouvre la fenêtre de l'agent.";
else if (q.action === 'repondre' && (!q.session_id || d.resultat_agent?.demande?.session_id !== q.session_id)) erreur = 'Demande inconnue.';
else if (q.action === 'repondre' && !q.message) erreur = 'Message vide.';
else if (q.action === 'refuser' && !d.resultat_agent?.demande?.session_id) erreur = 'Aucune demande préparée à refuser.';
return [{ json: { ok: !erreur, erreur, action: q.action, etudiant: e, demarche: d, session_id: q.session_id, message: q.message } }];

const { etudiant: e, demarche: d } = $('Contrôler').first().json;
const q = ($('Lire le questionnaire').first().json?.questionnaire?.reponses) || {};
const docs = $input.all().map(i => i.json).filter(x => x && x.type);
const doc = t => (docs.find(x => x.type === t) || {}).champs_extraits || {};
const bail = doc('bail'), paie = doc('fiche_paie'), contrat = doc('contrat_alternance'), ident = doc('piece_identite'), avis = doc('avis_imposition');
const v = x => (x === null || x === undefined || x === '') ? 'non renseigné' : x;
const on = x => x === true ? 'oui' : x === false ? 'non' : 'non renseigné';
const sim = d.resultat_agent?.reponse || {};
const coloc = q.mode_occupation === 'colocation';
const loyerCC = coloc && q.part_loyer_cc ? Number(q.part_loyer_cc) : (e.loyer_hors_charges != null ? Number(e.loyer_hors_charges) + Number(e.charges || 0) : null);
const TYPE = { prive: 'Studio, appartement, maison (location privée)', crous: 'Résidence Crous', foyer: 'Foyer ou résidence' };
const FAMILLE = { celibataire: 'seule', couple: 'en couple (vie maritale)', marie: 'mariée ou pacsée' };
const message = [
  "DOSSIER DE L'ÉTUDIANTE (vraie demande, préparée avec son accord ; utilise ces informations et rien d'autre) :",
  `Nom : ${v(e.nom)} | Prénom : ${v(e.prenom)} | Date de naissance : ${v(e.date_naissance)} | Lieu de naissance : ${v(e.lieu_naissance)}`,
  `Nationalité : ${v(e.nationalite)} | E-mail : ${v(e.email)} | Téléphone : ${v(e.telephone)}`,
  `Situation familiale : ${FAMILLE[q.situation_familiale] || v(q.situation_familiale)} | Enfants à charge : ${v(q.enfants_a_charge)}`,
  `Établissement : ${v(e.etablissement)} | Formation : ${v(e.formation)} | Situation professionnelle : ${q.statut === 'alternant' ? 'alternante (apprentissage)' : v(e.situation_pro)}`,
  '',
  'LOGEMENT (réponses de l\'étudiante à utiliser telles quelles) :',
  `Adresse : ${v(e.adresse_logement)} | Code postal : ${v(e.code_postal)}`,
  `Pour ce logement : elle paie un loyer | Elle est : ${coloc ? 'colocataire' : 'locataire'} (titulaire du bail : ${v(q.titulaire_bail)})`,
  `Le logement appartient à ses ascendants, descendants, elle-même ou une société à elle : ${on(q.lien_parente_bailleur)}`,
  `Type de logement : ${TYPE[q.type_logement] || v(e.type_logement)}`,
  `Surface du logement : ${v(q.surface_m2)} m² | Logement meublé : ${on(q.logement_meuble ?? (bail.meuble === true || /^(oui|true|meubl)/i.test(String(bail.meuble ?? '')) ? true : (bail.meuble === false || /^(non|false|vide)/i.test(String(bail.meuble ?? '')) ? false : null)))}`,
  coloc ? `Colocation : ${v(q.nb_colocataires)} personnes en tout ; sa part du loyer charges comprises : ${v(q.part_loyer_cc)} €/mois (loyer total du bail : ${v(e.loyer_hors_charges)} € + ${v(e.charges)} € de charges)` : `Loyer hors charges : ${v(e.loyer_hors_charges)} €/mois | Charges : ${v(e.charges)} €/mois`,
  `Loyer à déclarer (charges comprises, sa part) : ${v(loyerCC)} €/mois`,
  `Bailleur (nom sur le bail) : ${v(bail.bailleur)} | Type de bailleur : ${v(q.bailleur_type)} | Adresse du bailleur : ${v(q.bailleur_adresse_complete || bail.adresse_bailleur)}`,
  `Sur le bail : colocation ${v(bail.colocation)} | nombre d'occupants ${v(bail.nombre_occupants)}`,
  `Date d'entrée dans le logement (début du bail) : ${v(bail.date_debut)} | Durée du bail : ${v(bail.duree)} mois | Locataires sur le bail : ${v(bail.locataire)}`,
  `Déjà allocataire CAF : ${on(q.caf_deja_allocataire)}`,
  '',
  'EMPLOI ET RESSOURCES (lus sur ses documents) :',
  `Employeur : ${v(paie.employeur || contrat.employeur)} | SIRET : ${v(paie.siret_employeur || contrat.siret_employeur)} | Adresse : ${v(paie.adresse_employeur || contrat.adresse_employeur)}`,
  `Contrat : ${v(contrat.type_contrat)} du ${v(contrat.date_debut)} au ${v(contrat.date_fin)} | CFA : ${v(contrat.cfa)}`,
  `Dernière fiche de paie (${v(paie.periode)}) : brut ${v(paie.salaire_brut)} € | net social ${v(paie.net_social)} € | net à payer ${v(paie.net_a_payer)} €`,
  `Lieu de naissance (pièce d'identité) : ${v(e.lieu_naissance || ident.lieu_naissance)} | Sexe : ${v(ident.sexe)}`,
  `Avis d'imposition des parents ${v(avis.annee_avis)} : revenu fiscal de référence ${v(avis.revenu_fiscal_reference)} €`,
  `Revenus des 12 derniers mois : ${v(q.revenus_12_mois ?? e.ressources_12_mois)} € | Pension alimentaire reçue sur l'année : ${v(q.pension_recue_an)} € | Patrimoine de plus de 30 000 € : ${on(q.patrimoine_sup_30k)}`,
  `Boursière : ${e.boursier === true ? 'oui' : e.boursier === false ? 'non' : 'non renseigné'}`,
  `Simulation APL faite juste avant sur caf.fr : ${v(d.montant_estime)} €/mois (${v(sim.type_aide)}).`,
  '',
  "Prépare la demande d'aide au logement jusqu'à l'écran récapitulatif et arrête-toi avant la validation finale.",
  "Pour chaque question du formulaire, cherche la réponse dans cet ordre : 1) ce qui est déjà pré-rempli dans l'espace caf.fr (garde-le), 2) ce dossier (questionnaire et documents ci-dessus : bail, fiche de paie, contrat, pièce d'identité). Ne pose une question à l'étudiante que si la réponse n'est ni sur caf.fr ni dans ce dossier. Quand tu dois en poser, regroupe toutes les questions restantes dans un seul message. Une valeur « non renseigné » n'est pas une réponse : n'invente rien.",
].join('\n');
return [{ json: { demarche_id: d.id, ancien: d.resultat_agent || {}, requete: { agent: 'demande-apl-caf', messages: message, timezone: 'Europe/Paris', max_time_s: 2400, idle_timeout_s: 1800 } } }];

const p = $('Préparer la demande').first().json;
const s = $("Lancer l'agent demande-apl-caf").first().json;
const partage = $input.first().json || {};
const lien = partage.share_url ? (String(partage.share_url).startsWith('http') ? partage.share_url : 'https://agp.eu.hcompany.ai' + partage.share_url) : null;
return [{ json: { id: p.demarche_id, resultat_agent: { ...p.ancien, demande: { session_id: s.id, lien_public: lien, lien_session: s.agent_view_url || null, statut: 'en_cours', lance_le: new Date().toISOString() } }, updated_at: new Date().toISOString() } }];

const s = $input.first().json || {};
const st = s.status?.status ?? s.status;
let r = s.latest_answer;
if (typeof r === 'string') { try { r = JSON.parse(r.replace(/```json|```/g, '').trim()); } catch (e) { r = { remarques: r }; } }
const fini = ['completed', 'failed', 'timed_out', 'interrupted'].includes(st)
  || (r && ['pret_a_valider', 'bloque'].includes(r.statut))
  || $runIndex >= 120; // 40 minutes au plus
return [{ json: { fini, st, r: r || null } }];

const d = $input.first().json;
const { st, r } = $('Terminé ?').last().json;
const statut = r?.statut === 'pret_a_valider' ? 'pret_a_valider' : (r?.statut === 'bloque' || ['failed', 'timed_out', 'interrupted'].includes(st) ? 'bloque' : (r?.statut || 'bloque'));
const avant = d.resultat_agent?.demande || {};
return [{ json: { id: d.id, resultat_agent: { ...(d.resultat_agent || {}), demande: { ...avant, statut, etape_atteinte: r?.etape_atteinte || null, recapitulatif: r?.recapitulatif || null, questions_sans_reponse: r?.questions_sans_reponse || [], remarques: r?.remarques || null, statut_h: st, fini_le: new Date().toISOString() } }, updated_at: new Date().toISOString() } }];

const { demarche: d } = $input.first().json;
const r = d.resultat_agent || {};
return [{ json: { id: d.id, resultat_agent: { ...r, demande: { ...(r.demande || {}), statut: 'refusee', refusee_le: new Date().toISOString() } }, updated_at: new Date().toISOString() } }];
